package com.example.microsave.loan.service;
import com.example.microsave.contribution.repository.ContributionRepository;import com.example.microsave.exception.*;import com.example.microsave.loan.dto.LoanDTO;import com.example.microsave.loan.entity.Loan;import com.example.microsave.loan.repository.LoanRepository;import com.example.microsave.member.repository.MemberRepository;import java.math.BigDecimal;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class LoanService {private final LoanRepository repo;private final MemberRepository members;private final ContributionRepository contributions;public LoanService(LoanRepository r,MemberRepository m,ContributionRepository c){repo=r;members=m;contributions=c;}private Loan get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Loan not found: "+id));}private LoanDTO map(Loan l){BigDecimal repaid=l.getAmount().subtract(l.getOutstandingAmount());return new LoanDTO(l.getId(),l.getMember().getId(),l.getAmount(),l.getLoanDate(),l.getOutstandingAmount(),l.getStatus(),l.getPurpose(),repaid);}public List<LoanDTO> all(){return repo.findAll().stream().map(this::map).toList();}public List<LoanDTO> byMember(Long id){if(!members.existsById(id))throw new ResourceNotFoundException("Member not found: "+id);return repo.findByMember_Id(id).stream().map(this::map).toList();}public LoanDTO one(Long id){return map(get(id));}public LoanDTO create(LoanDTO d){var member=members.findById(d.memberId()).orElseThrow(()->new ResourceNotFoundException("Member not found: "+d.memberId()));if(repo.existsByMember_IdAndStatusAndOutstandingAmountGreaterThan(d.memberId(),"ACTIVE",BigDecimal.ZERO))throw new BusinessRuleException("Member already has an outstanding loan.");BigDecimal pool=contributions.totalByGroup(member.getGroup().getId()).subtract(repo.outstandingByGroup(member.getGroup().getId()));if(d.amount().compareTo(pool)>0)throw new BusinessRuleException("Loan amount exceeds the group's available pool.");Loan l=new Loan();l.setMember(member);l.setAmount(d.amount());l.setOutstandingAmount(d.amount());l.setLoanDate(d.loanDate());l.setStatus("ACTIVE");l.setPurpose(d.purpose());return map(repo.save(l));}public LoanDTO update(Long id,LoanDTO d){Loan l=get(id);if(l.getOutstandingAmount().compareTo(l.getAmount())!=0||!"ACTIVE".equals(l.getStatus()))throw new BusinessRuleException("A loan with repayments cannot be edited; record corrections through repayments.");var m=members.findById(d.memberId()).orElseThrow(()->new ResourceNotFoundException("Member not found: "+d.memberId()));if(!m.getId().equals(l.getMember().getId())&&repo.existsByMember_IdAndStatusAndOutstandingAmountGreaterThan(m.getId(),"ACTIVE",BigDecimal.ZERO))throw new BusinessRuleException("Member already has an outstanding loan.");BigDecimal existingBalanceInTargetGroup=m.getGroup().getId().equals(l.getMember().getGroup().getId())?l.getOutstandingAmount():BigDecimal.ZERO;BigDecimal pool=contributions.totalByGroup(m.getGroup().getId()).subtract(repo.outstandingByGroup(m.getGroup().getId())).add(existingBalanceInTargetGroup);if(d.amount().compareTo(pool)>0)throw new BusinessRuleException("Loan amount exceeds the group's available pool.");l.setMember(m);l.setAmount(d.amount());l.setOutstandingAmount(d.amount());l.setLoanDate(d.loanDate());l.setPurpose(d.purpose());return map(repo.save(l));}public void delete(Long id){Loan l=get(id);if(l.getOutstandingAmount().compareTo(l.getAmount())!=0)throw new BusinessRuleException("A loan with repayments cannot be deleted.");repo.delete(l);}public BigDecimal totalOutstanding(){return repo.outstandingAll();}}
